import heapq
from itertools import combinations


def _routes(minimum_duration, exact_coupons):
    def solve(data):
        required = data.get("required", [])
        full = (1 << len(required)) - 1
        node_mask = [0] * data["n"]
        for i, node in enumerate(required):
            node_mask[node] |= 1 << i
        start = data["source"]
        initial_mask = node_mask[start]
        initial = (start, initial_mask, data["coupons"])
        best = {initial: data["start"]}
        queue = [(data["start"], start, initial_mask, data["coupons"])]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        while queue:
            arrival, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if best.get(state) != arrival:
                continue
            if (node == data["target"] and mask == full
                    and (not exact_coupons or remaining == 0)):
                return {"arrival": arrival}
            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(minimum_duration,
                                   edge["duration"] - edge.get("discount", 0))
                    options.append((duration, remaining - 1))
                for duration, next_remaining in options:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | node_mask[next_node]
                    next_state = (next_node, next_mask, next_remaining)
                    if next_time < best.get(next_state, float("inf")):
                        best[next_state] = next_time
                        heapq.heappush(queue, (next_time, next_node, next_mask,
                                               next_remaining))
        return {"arrival": None}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        quotient, remainder = divmod(numerator, denominator)
        if mode == "half_up" and 2 * remainder >= denominator:
            quotient += 1
        return quotient

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        best_vector = None
        best_install = None

        def search(assignments, constraints):
            nonlocal best_vector, best_install
            for name, version in assignments.items():
                if any(not low <= version <= high
                       for low, high in constraints.get(name, [])):
                    return
            pending = [name for name in constraints if name not in assignments]
            if not pending:
                # Every selected row contributes its active edges; reject cycles.
                edges = {}
                for name, version in assignments.items():
                    row = next(row for row in packages[name]
                               if row["version"] == version)
                    edges[name] = [dep["name"] for dep in row.get("deps", [])
                                   if not dep.get("feature")
                                   or dep.get("feature") in features]
                finished, active = set(), set()

                def visit(name):
                    if name in active:
                        return False
                    if name in finished:
                        return True
                    active.add(name)
                    if any(not visit(other) for other in edges.get(name, [])):
                        return False
                    active.remove(name)
                    finished.add(name)
                    return True

                if not all(visit(name) for name in edges):
                    return
                vector = tuple(assignments[name] if name in assignments else -1
                               for name in names)
                if best_vector is None or vector > best_vector:
                    best_vector = vector
                    best_install = dict(assignments)
                return

            name = min(pending)
            rows = [row for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])
                    and all(low <= row["version"] <= high
                            for low, high in constraints[name])]
            for row in sorted(rows, key=lambda item: item["version"], reverse=True):
                new_assignments = dict(assignments)
                new_assignments[name] = row["version"]
                new_constraints = {key: list(value)
                                   for key, value in constraints.items()}
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    dep_name = dep["name"]
                    new_constraints.setdefault(dep_name, []).append(
                        (dep["min"], dep["max"]))
                search(new_assignments, new_constraints)

        initial_constraints = {name: [tuple(bounds)]
                               for name, bounds in roots.items()}
        search({}, initial_constraints)
        if best_install is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_install}
    return solve


def _build_component_08():
    def feasible(selected, data):
        ids = {job["id"] for job in selected}
        if not set(data.get("mandatory", [])).issubset(ids):
            return False
        counts = {}
        for job in selected:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        for group, (low, high) in data.get("quotas", {}).items():
            count = counts.get(group, 0)
            if not low <= count <= high:
                return False
        active = []
        for job in sorted(selected,
                          key=lambda item: (item["start"], item["end"], item["id"])):
            while active and active[0] <= job["start"]:
                heapq.heappop(active)
            heapq.heappush(active, job["end"])
            if len(active) > 2:
                return False
        return True

    def solve(data):
        blocked = set(data.get("blocked", []))
        jobs = [job for job in data["jobs"] if job["id"] not in blocked]
        k = data["k"]
        best_value = None
        best_ids = None
        for selected in combinations(jobs, k):
            if not feasible(selected, data):
                continue
            value = sum(job["value"] for job in selected)
            ids = sorted(job["id"] for job in selected)
            if (best_value is None or value > best_value
                    or (value == best_value and ids > best_ids)):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


SOLVERS = {
    "component_01": _routes(1, True),
    "component_02": _routes(2, False),
    "component_03": _routes(2, True),
    "component_04": _routes(1, False),
    "component_05": _routes(1, True),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
